new file mode 100644
index 000000000..88fd36201
--- /dev/null
+++ b/crates/vb_storage/src/admission/acceptance_sequence_boundary_tests.rs
@@ -0,0 +1,128 @@
+//! Boundary tests for sequence counter corruption and overflow conditions.
+
+use crate::admission::*;
+use crate::error::JournalError;
+use vb_core::RuntimePolicy;
+
+use super::{minimal_workflow, temp_journal};
+
+#[test]
+fn corrupted_counter_length_7_causes_malformed_row() -> Result<(), String> {
+    let tj = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
+    let journal = &tj.journal;
+
+    journal
+        .artifact_acceptance
+        .insert(b"last_issued", &[0, 0, 0, 0, 0, 0, 0])
+        .map_err(|e| format!("insert 7-byte counter: {e}"))?;
+
+    let workflow = minimal_workflow().map_err(|e| format!("minimal_workflow: {e}"))?;
+    let result = submit_artifact(journal, &workflow, RuntimePolicy::Relaxed);
+
+    let matches_malformed = matches!(
+        result,
+        Err(JournalError::MalformedKeyspaceRow {
+            prefix: 0,
+            expected_len: 8,
+            actual_len: 7
+        })
+    );
+    assert!(
+        matches_malformed,
+        "expected MalformedKeyspaceRow actual=7, got {result:?}"
+    );
+
+    let counter = journal
+        .artifact_acceptance
+        .get(b"last_issued")
+        .map_err(|e| format!("read counter: {e}"))?
+        .ok_or_else(|| "counter should still exist")?;
+    assert_eq!(
+        counter,
+        &[0, 0, 0, 0, 0, 0, 0],
+        "counter should be unchanged"
+    );
+    assert!(
+        journal.compiled_ir.iter().next().is_none(),
+        "no compiled_ir written"
+    );
+
+    Ok(())
+}
+
+#[test]
+fn corrupted_counter_length_9_causes_malformed_row() -> Result<(), String> {
+    let tj = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
+    let journal = &tj.journal;
+
+    journal
+        .artifact_acceptance
+        .insert(b"last_issued", &[0, 0, 0, 0, 0, 0, 0, 0, 0])
+        .map_err(|e| format!("insert 9-byte counter: {e}"))?;
+
+    let workflow = minimal_workflow().map_err(|e| format!("minimal_workflow: {e}"))?;
+    let result = submit_artifact(journal, &workflow, RuntimePolicy::Relaxed);
+
+    let matches_malformed = matches!(
+        result,
+        Err(JournalError::MalformedKeyspaceRow {
+            prefix: 0,
+            expected_len: 8,
+            actual_len: 9
+        })
+    );
+    assert!(
+        matches_malformed,
+        "expected MalformedKeyspaceRow actual=9, got {result:?}"
+    );
+
+    let counter = journal
+        .artifact_acceptance
+        .get(b"last_issued")
+        .map_err(|e| format!("read counter: {e}"))?
+        .ok_or_else(|| "counter should still exist")?;
+    assert_eq!(
+        counter,
+        &[0, 0, 0, 0, 0, 0, 0, 0, 0],
+        "counter should be unchanged"
+    );
+    assert!(
+        journal.compiled_ir.iter().next().is_none(),
+        "no compiled_ir written"
+    );
+
+    Ok(())
+}
+
+#[test]
+fn counter_at_u64_max_causes_sequence_overflow() -> Result<(), String> {
+    let tj = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
+    let journal = &tj.journal;
+
+    let max_bytes = u64::MAX.to_be_bytes();
+    journal
+        .artifact_acceptance
+        .insert(b"last_issued", &max_bytes)
+        .map_err(|e| format!("insert u64::MAX counter: {e}"))?;
+
+    let workflow = minimal_workflow().map_err(|e| format!("minimal_workflow: {e}"))?;
+    let result = submit_artifact(journal, &workflow, RuntimePolicy::Relaxed);
+
+    assert!(
+        matches!(result, Err(JournalError::SequenceOverflow)),
+        "expected SequenceOverflow, got {result:?}"
+    );
+
+    let counter = journal
+        .artifact_acceptance
+        .get(b"last_issued")
+        .map_err(|e| format!("read counter: {e}"))?
+        .ok_or_else(|| "counter should still exist")?;
+    assert_eq!(counter, &max_bytes, "counter should be unchanged");
+    assert!(
+        journal.compiled_ir.iter().next().is_none(),
+        "no compiled_ir written"
+    );
+
+    Ok(())
+}
diff --git a/crates/vb_storage/src/admission/acceptance_sequence_concurrency_tests.rs b/crates/vb_storage/src/admission/acceptance_sequence_concurrency_tests.rs
new file mode 100644
index 000000000..0c0e4ebe6
--- /dev/null
+++ b/crates/vb_storage/src/admission/acceptance_sequence_concurrency_tests.rs
@@ -0,0 +1,109 @@
+//! Concurrency test for the artifact acceptance sequence counter.
+//!
+//! Tests that 8 concurrent submissions to the same journal each receive a
+//! unique sequence number (1-8), proving the write_lock serialization and
+//! counter atomicity. Status: PENDING compiler and test execution by coordinator.
+
+use std::collections::HashSet;
+use vb_core::RuntimePolicy;
+
+use super::{minimal_workflow, temp_journal};
+use crate::admission::*;
+
+/// 8 concurrent submissions must all succeed with unique sequences 1-8.
+#[test]
+fn eight_concurrent_submissions_get_unique_sequences_1_through_8() -> Result<(), String> {
+    let journal = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
+    let workflow = minimal_workflow()?;
+
+    let journal_ref = &journal;
+    let artifacts = std::thread::scope(|scope| -> Result<Vec<AcceptedArtifact>, String> {
+        let mut handles = Vec::with_capacity(8);
+        for _ in 0..8 {
+            let wf = workflow.clone();
+            let handle = scope.spawn(move || {
+                submit_artifact(journal_ref, &wf, RuntimePolicy::Relaxed)
+                    .map_err(|e| format!("submit_artifact failed: {e}"))
+            });
+            handles.push(handle);
+        }
+
+        let mut results = Vec::with_capacity(8);
+        for handle in handles {
+            let artifact = handle
+                .join()
+                .map_err(|e| format!("thread join failed: {e:?}"))??;
+            results.push(artifact);
+        }
+        Ok(results)
+    })?;
+
+    if artifacts.len() != 8 {
+        return Err(format!("expected 8 artifacts, got {}", artifacts.len()));
+    }
+
+    // Sequences must be unique and form the set {1, 2, 3, 4, 5, 6, 7, 8}.
+    let mut seqs = Vec::with_capacity(8);
+    for artifact in &artifacts {
+        seqs.push(artifact.accepted_at_seq.get());
+    }
+    let mut sorted_seqs = seqs.clone();
+    sorted_seqs.sort();
+    let expected: Vec<u64> = (1..=8).collect();
+    if sorted_seqs != expected {
+        return Err(format!("sequences must be 1..=8, got {:?}", sorted_seqs));
+    }
+
+    // All digests must be unique (HashSet, not Ord sort).
+    let mut digests = HashSet::new();
+    for artifact in &artifacts {
+        digests.insert(artifact.digest);
