        let second = submit_artifact(&journal, &workflow, RuntimePolicy::Strict)
            .map_err(|e| format!("second submit: {e}"))?;
        assert_second_seq(&second);
        assert_readback_verified(&journal, &second, RuntimePolicy::Strict)?;
    }

    Ok(())
}

